    public Object parseTransfer(Object transfer, Map<String, Object> currency)
    {
        //
        // transfer
        //
        //     {
        //         "balance": 1350.5,
        //         "blockedBalance": 0,
        //         "createdAt": "2023-09-13T14:05:42.149Z",
        //         "currency": "EUR",
        //         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        //         "rawBalance": "1350.5",
        //         "rawBlockedBalance": "0",
        //         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        //     }
        //
        // fetchTransfers
        //
        //     {
        //         "amount": 100,
        //         "createdAt": "2025-03-10T09:30:00.000Z",
        //         "currency": "EUR",
        //         "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        //         "movementType": "deposit",
        //         "serviceOrderName": "wallet",
        //         "status": "completed",
        //         "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        //     }
        //
        String currencyId = this.safeString(transfer, "currency");
        String movementType = this.safeString(transfer, "movementType");
        Map<String, Object> accountsById = this.safeDict(this.options, "accountsById", new HashMap<String, Object>() {{}});
        String fromAccount = null;
        String toAccount = null;
        String id = null;
        Long timestamp = null;
        String status = null;
        if (!java.util.Objects.equals(movementType, null))
        {
            // a movement from the historical list
            id = this.safeString(transfer, "id");
            timestamp = this.parse8601(this.safeString(transfer, "createdAt"));
            status = this.parseTransferStatus(this.safeString(transfer, "status"));
            String wallet = this.safeString(accountsById, "wallet");
            String trading = this.safeString(accountsById, "trading");
            fromAccount = (((java.util.Objects.equals(movementType, "deposit")))) ? wallet : trading;
            toAccount = (((java.util.Objects.equals(movementType, "deposit")))) ? trading : wallet;
        } else
        {
            // the trading wallet returned by deposit/withdraw, createdAt is the wallet creation date
            status = "ok";
        }
        {
            HashMap<String, Object> h2kMap0 = new HashMap<String, Object>();
            h2kMap0.put("info", transfer);
            h2kMap0.put("id", id);
            h2kMap0.put("timestamp", timestamp);
            h2kMap0.put("datetime", this.iso8601(timestamp));
            h2kMap0.put("currency", this.safeCurrencyCode(currencyId, currency));
            h2kMap0.put("amount", this.safeNumber(transfer, "amount", (Object) null));
            h2kMap0.put("fromAccount", fromAccount);
            h2kMap0.put("toAccount", toAccount);
            h2kMap0.put("status", status);
            return h2kMap0;
        }
    }

